mkdir -p src/db scripts
cat > src/db/schema.ts <<'EOF'
import { date, pgTable, serial, text } from "drizzle-orm/pg-core";

export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  email: text("email").notNull().unique(),
  name: text("name").notNull(),
  createdAt: date("created_at", { mode: "string" }).notNull().defaultNow(),
});

export type UserRow = typeof users.$inferSelect;
export type NewUserRow = typeof users.$inferInsert;
EOF
cat > src/db/index.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import * as schema from "./schema";

const globalForDb = globalThis as unknown as { pgClient?: postgres.Sql };

function createClient() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");
  return postgres(url);
}

// Reuse one client across dev hot reloads to avoid exhausting connections.
const client = (globalForDb.pgClient ??= createClient());

export const db = drizzle(client, { schema });
EOF
cat > src/db/queries.ts <<'EOF'
import { asc, eq } from "drizzle-orm";
import { db } from "./index";
import { users, type NewUserRow, type UserRow } from "./schema";

export async function selectUsers(): Promise<UserRow[]> {
  return db.select().from(users).orderBy(asc(users.id));
}

export async function selectUserById(id: number): Promise<UserRow | undefined> {
  const [row] = await db.select().from(users).where(eq(users.id, id));
  return row;
}

export async function selectFirstUser(): Promise<UserRow | undefined> {
  const [row] = await db.select().from(users).orderBy(asc(users.id)).limit(1);
  return row;
}

export async function insertUser(values: NewUserRow): Promise<UserRow> {
  const [row] = await db.insert(users).values(values).returning();
  return row;
}
EOF
cat > src/lib/users.ts <<'EOF'
import { selectFirstUser, selectUserById, selectUsers } from "@/db/queries";
import type { UserRow } from "@/db/schema";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

function toUser(row: UserRow): User {
  return { ...row, id: String(row.id) };
}

export async function listUsers(): Promise<User[]> {
  return (await selectUsers()).map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  // Ids are integers in the database; anything else can't match a user.
  if (!/^\d+$/.test(id)) return undefined;
  const numericId = Number(id);
  if (!Number.isSafeInteger(numericId) || numericId > 2147483647) return undefined;
  const row = await selectUserById(numericId);
  return row && toUser(row);
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  const row = await selectFirstUser();
  return row && toUser(row);
}
EOF
cat > drizzle.config.ts <<'EOF'
import { defineConfig } from "drizzle-kit";

export default defineConfig({
  dialect: "postgresql",
  schema: "./src/db/schema.ts",
  out: "./drizzle",
  dbCredentials: { url: process.env.DATABASE_URL! },
});
EOF
cat > scripts/migrate.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";

const url = process.env.DATABASE_URL;
if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");

const client = postgres(url, { max: 1 });
await migrate(drizzle(client), { migrationsFolder: "./drizzle" });
await client.end();
console.log("Migrations applied");
EOF
cat > scripts/seed.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { users } from "../src/db/schema";

const url = process.env.DATABASE_URL;
if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");

const client = postgres(url, { max: 1 });
await drizzle(client)
  .insert(users)
  .values([
    { email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
    { email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
  ])
  .onConflictDoNothing({ target: users.email });
await client.end();
console.log("Seeded");
EOF
cat > .env.example <<'EOF'
# Postgres connection string (placeholder credentials — matches docker-compose.yml)
DATABASE_URL=postgres://app:change-me@localhost:5432/app
EOF
cat > docker-compose.yml <<'EOF'
services:
  db:
    image: postgres:17
    environment:
      POSTGRES_USER: app
      POSTGRES_PASSWORD: change-me
      POSTGRES_DB: app
    ports:
      - "5432:5432"
    volumes:
      - pgdata:/var/lib/postgresql/data
volumes:
  pgdata:
EOF
